<?php
namespace Database\Seeders;
use App\Models\Organization;use App\Models\User;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
final class DatabaseSeeder extends Seeder{public function run():void{$admin=User::create(['name'=>'Süper Admin','email'=>'admin@demo.test','password'=>Hash::make('ChangeMe!2026'),'email_verified_at'=>now(),'is_super_admin'=>true]);$demo=User::create(['name'=>'Demo Analist','email'=>'demo@demo.test','password'=>Hash::make('ChangeMe!2026'),'email_verified_at'=>now()]);$org=Organization::create(['name'=>'Demo Ajans','slug'=>'demo-ajans','owner_id'=>$demo->id]);$org->users()->attach($demo->id,['role'=>'owner','status'=>'active']);$limits=['competitor_limit'=>3,'data_credits'=>1000,'ai_credits'=>100,'report_credits'=>10,'team_member_limit'=>2];foreach(['instagram'=>'Instagram','tiktok'=>'TikTok','youtube'=>'YouTube','web'=>'Web'] as $slug=>$name){$pid=(string)Str::uuid();DB::table('products')->insert(['id'=>$pid,'slug'=>$slug,'name'=>$name,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);for($level=1;$level<=3;$level++){$plan=(string)Str::uuid();DB::table('plans')->insert(['id'=>$plan,'product_id'=>$pid,'name'=>"$name $level",'level'=>$level,'price_minor'=>$level*99000,'currency'=>'TRY','visible'=>true,'created_at'=>now(),'updated_at'=>now()]);foreach($limits as $key=>$value)DB::table('plan_entitlements')->insert(['id'=>(string)Str::uuid(),'plan_id'=>$plan,'key'=>$key,'value'=>json_encode($value*$level),'created_at'=>now(),'updated_at'=>now()]);foreach(['data','ai','report','video_ai','promotion'] as $type)DB::table('credit_wallets')->insert(['id'=>(string)Str::uuid(),'organization_id'=>$org->id,'product_id'=>$pid,'credit_type'=>$type,'subscription_balance'=>$type==='data'?1000:100,'promotion_balance'=>0,'purchased_balance'=>0,'reserved_balance'=>0,'created_at'=>now(),'updated_at'=>now()]);}}}}
